package mx.com.mesaregia.pagos.api.controller;
import jakarta.validation.Valid; import mx.com.mesaregia.pagos.api.request.*; import mx.com.mesaregia.pagos.api.response.*; import mx.com.mesaregia.pagos.application.service.*; import mx.com.mesaregia.pagos.domain.enums.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/pagos") @Validated
public class PagoController {private final PagoQueryService query;private final PagoService pagos;private final MovimientoCuentaService movimientos;public PagoController(PagoQueryService q,PagoService p,MovimientoCuentaService m){query=q;pagos=p;movimientos=m;}
 @GetMapping @PreAuthorize("hasAuthority('pagos.consultar')") public PageResponse<MovimientoPagoResponse> buscar(@RequestParam(required=false)String folioCotizacion,@RequestParam(required=false)Integer version,@RequestParam(required=false)String cliente,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate fechaInicio,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate fechaFin,@RequestParam(required=false)MetodoPago metodo,@RequestParam(required=false)TipoRegistroPago tipo,@RequestParam(required=false)EstadoCuentaCobro estado,@RequestParam(required=false)Long idUsuario,@PageableDefault(size=20,sort="fechaHora",direction=Sort.Direction.DESC)Pageable pageable){return query.buscar(folioCotizacion,version,cliente,fechaInicio,fechaFin,metodo,tipo,estado,idUsuario,pageable);}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('pagos.gestionar')") public PagoRegistroResponse registrar(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody PagoCreateRequest request){return pagos.registrar(key,request);}
 @PostMapping("/{id}/compensaciones") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('pagos.gestionar')") public CompensacionResponse compensar(@PathVariable Long id,@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody CompensacionCreateRequest request){return movimientos.compensar(id,key,request);}
}
